    # Parse sign
    if dollars.startswith('-'):
        sign = '-'
        dollars = dollars[1:]
    else:
        sign = '+'

    # Split into integer and fractional parts
    if '.' in dollars:
        integer_part, frac_part = dollars.split('.')
    else:
        integer_part = dollars
        frac_part = ''

    # Pad or truncate fractional part to exactly 2 digits
    if len(frac_part) == 0:
        frac_part = '00'
    elif len(frac_part) == 1:
        frac_part = frac_part + '0'
    elif len(frac_part) > 2:
        frac_part = frac_part[:2]

    # Combine to get total cents (minor units)
    if integer_part == '' or integer_part == '0':
        integer_part = '0'
    cents_str = integer_part + frac_part

    # Remove leading zeros but keep at least one digit
    cents_str = cents_str.lstrip('0')
    if cents_str == '':
        cents_str = '0'

    # Compute check digit: sum of decimal digits mod 10
    digit_sum = sum(int(ch) for ch in cents_str)
    check_digit = digit_sum % 10

    return f"{sign}{cents_str}#{check_digit}"

